<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#C678DD;">    or</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">  $0b00000101</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">, %</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">rax</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">                   # rax = 0xa5</span></span>
